	private void assertParity(String query) {
		List<String> compiled = run(query, true);
		List<String> interpreted = run(query, false);
		assertThat(interpreted).isEqualTo(compiled);
	}

	/**
	 * Parity plus engagement: the interpreted arm must actually open the aggregate kernel rung (with janino off,
	 * {@code AGG_OPENED} can only be advanced by {@code LmdbNativeKernelInterpreter}), so the node this query pins is
	 * provably executed rather than silently served by a fallback strategy.
	 */
	private void assertParityInterpreterServed(String query) {
		List<String> compiled = run(query, true);
		LmdbNativeKernelExecution.resetMetrics();
		List<String> interpreted = run(query, false);
		assertThat(interpreted).isEqualTo(compiled);
		assertThat(LmdbNativeKernelExecution.AGG_OPENED.get())
				.as("the interpreted arm must serve this query through the kernel interpreter")
				.isPositive();
	}

	private void assertParityInterpreterOrSemanticNative(String query) {
		List<String> compiled = run(query, true);
		LmdbNativeKernelExecution.resetMetrics();
		long semanticBefore = KernelExecutionTestAccess.semanticNativeCompiles();
		long hostedBefore = KernelExecutionTestAccess.hostedGenericCompiles();
		long islandsBefore = KernelExecutionTestAccess.islandCompiles();
		List<String> interpreted = run(query, false);
		assertThat(interpreted).isEqualTo(compiled);
		assertThat(LmdbNativeKernelExecution.AGG_OPENED.get() > 0L
				|| KernelExecutionTestAccess.semanticNativeCompiles() > semanticBefore).isTrue();
		assertThat(KernelExecutionTestAccess.hostedGenericCompiles()).isEqualTo(hostedBefore);
		assertThat(KernelExecutionTestAccess.islandCompiles()).isEqualTo(islandsBefore);
	}

	/**
	 * Runs the query with janino codegen forced on (compiled tier, synchronous) or off (interpreted tier). System
	 * properties are read per evaluation in this engine; a fresh connection per arm keeps strategy state from leaking
	 * across arms.
	 */
	private List<String> run(String query, boolean janino) {
		System.setProperty("rdf4j.lmdb.janinoCodegen.enabled", Boolean.toString(janino));
		try (SailRepositoryConnection connection = repository.getConnection()) {
			return canonical(QueryResults.asList(connection.prepareTupleQuery(query).evaluate()));
		}
	}

	/** Sorted multiset of canonical row strings, insensitive to row and binding order. */
	private static List<String> canonical(List<BindingSet> rows) {
		List<String> result = new ArrayList<>(rows.size());
		for (BindingSet row : rows) {
			List<String> bindings = new ArrayList<>(row.size());
			for (Binding binding : row) {
				bindings.add(binding.getName() + "=" + binding.getValue());
			}
			bindings.sort(String::compareTo);
			result.add(String.join("|", bindings));
		}
		result.sort(String::compareTo);
		return result;
	}

	private static String prefixes() {
		return "PREFIX ex: <" + EX + ">\nPREFIX xsd: <http://www.w3.org/2001/XMLSchema#>\n";
	}
